# AWS KMS encryption for SageMaker model artifacts
import boto3

sagemaker = boto3.client('sagemaker')

response = sagemaker.create_model(
    ModelName='secure-fraud-model-v2',
    PrimaryContainer={
        'Image': '123456789.dkr.ecr.us-east-1.amazonaws.com/fraud-detector:latest',
        'ModelDataUrl': 's3://models/fraud-detector.tar.gz',
        'Environment': {
            'MODEL_SERVER_TIMEOUT': '300'
        }
    },
    ExecutionRoleArn='arn:aws:iam::123456789:role/SageMakerRole',
    EnableNetworkIsolation=True,  # No internet access
    VpcConfig={
        'SecurityGroupIds': ['sg-0123456789abcdef'],
        'Subnets': ['subnet-abc123', 'subnet-def456']
    }
)

# Model artifacts encrypted with KMS key at rest
# Network isolation prevents data exfiltration

# Cloud-agnostic model serving abstraction (Python)
