import os

class ModelServing(ABC):
    @abstractmethod
    def deploy(self, model_uri: str, instance_type: str):
        pass

class SageMakerServing(ModelServing):
    def deploy(self, model_uri: str, instance_type: str):
        # AWS SageMaker-specific deployment
        pass

class VertexAIServing(ModelServing):
    def deploy(self, model_uri: str, instance_type: str):
        # GCP Vertex AI-specific deployment
        pass

# Client code remains cloud-agnostic
serving = SageMakerServing() if os.getenv('CLOUD')=='aws' else VertexAIServing()
serving.deploy('s3://models/fraud-v2', 'ml.g4dn.xlarge')
